# Compare R=7..10 full cost DP via a separately written exhaustive-recursion envelope.
import random,subprocess,bisect,time
from functools import lru_cache
WIDTH=[16,8,4];LANES=[4,8,16]
def pg(s,b,m):
 K=s if b==0 else b-1;return (32+4*b+K*WIDTH[m]+63)//64
def comps(s):
 for b in range(2,min(9,s)+1):
  def rec(rem,k,p):
   if k==1:yield p+[rem]
   else:
    for x in range(1,rem-k+2):yield from rec(rem-x,k-1,p+[x])
  yield from rec(s,b,[])
def stats(st,vb):
 R=len(st);Q=[[0]*(R+1) for _ in range(R+1)];T=[[0]*(R+1) for _ in range(R+1)];qr=[0]*R
 for rep,aa in vb:
  tu=[0]*R
  for a in aa:r=bisect.bisect_right(st,a)-1;qr[r]+=rep;tu[r]=1
  pr=[0]
  for x in tu:pr.append(pr[-1]+x)
  for i in range(R):
   for j in range(i+1,R+1):
    if pr[j]-pr[i]:T[i][j]+=rep
 pr=[0]
 for x in qr:pr.append(pr[-1]+x)
 for i in range(R):
  for j in range(i+1,R+1):Q[i][j]=pr[j]-pr[i]
 return Q,T
def brute(st,Q,T,cost,C):
 R=len(st)
 @lru_cache(None)
 def sub(i,j):
  s=j-i;qv=Q[i][j];tv=T[i][j];sp=st[j-1]-st[i];lg=[0]
  if sp<1<<64:lg.append(1)
  if sp<1<<32:lg.append(2)
  out={}
  def add(w,p,c):
   if c<=C and (c not in out or (w,p)<out[c]):out[c]=(w,p)
  if s<=8:
   for m in lg:
    P=pg(s,0,m);kw=(s+LANES[m]-1)//LANES[m]+cost[2][m];ba=kw*qv
    add(ba+P*cost[1]*tv,P,0)
    if P<=C:add(ba+P*cost[0]*tv,P,P)
  for co in comps(s):
   b=len(co);com={0:(0,0)};pos=i
   for x in co:
    vv=sub(pos,pos+x);ng={}
    for c1,(w1,p1) in com.items():
     for c2,(w2,p2) in vv:
      c=c1+c2
      if c>C:continue
      ca=(w1+w2,p1+p2)
      if c not in ng or ca<ng[c]:ng[c]=ca
    com=ng;pos+=x
   for cs,(ws,ps) in com.items():
    for m in lg:
     P=pg(s,b,m);kw=(b-1+LANES[m]-1)//LANES[m]+cost[2][m];ba=ws+kw*qv
     add(ba+P*cost[1]*tv,ps+P,cs)
     if cs+P<=C:add(ba+P*cost[0]*tv,ps+P,cs+P)
  return tuple(out.items())
 return dict(sub(0,R))
def runplan(st,hops,bursts,cost,C):
 lines=['PLAN 1',f'{C} {cost[0]} {cost[1]} {cost[2][0]} {cost[2][1]} {cost[2][2]} 1 {len(bursts)}',str(len(st))]
 lines += [f'{x:032x} {-1 if h is None else h}' for x,h in zip(st,hops)]
 for v,r,aa in bursts:
  row=f'{v} {r} {len(aa)}'
  if aa:row+=' '+' '.join(f'{a:032x}' for a in aa)
  lines.append(row)
 p=subprocess.run(['tmp/engine_test'],input=('\n'.join(lines)+'\n').encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if p.returncode:raise RuntimeError(p.stderr.decode())
 o=p.stdout.decode().splitlines();at=1
 for v,r,aa in bursts:A=int(o[at]);at+=1+A
 return tuple(map(int,o[at].split()))
random.seed(404)
t0=time.time()
for trial in range(25):
 R=random.randint(7,10);C=random.randint(0,3)
 st=[0]
 for _ in range(R-1):st.append(st[-1]+random.randint(1,random.choice([5,100,1<<35])))
 hops=[None if random.random()<.1 else random.randint(0,9) for _ in range(R)]
 bursts=[]
 for _ in range(random.randint(0,3)):
  rep=random.randint(1,4);aa=[]
  for __ in range(random.randint(0,5)):
   r=random.randrange(R);end=st[r+1] if r+1<R else st[r]+100
   aa.append(random.randrange(st[r],min(end,st[r]+100)))
  bursts.append((0,rep,aa))
 Q,T=stats(st,[(r,a) for v,r,a in bursts]);cost=[random.randint(1,3),random.randint(3,8),[random.randint(0,2) for _ in range(3)]]
 by=brute(st,Q,T,cost,C);bw,bp=min(by.values());fixed=1+(4*R+63)//64;exp=(bw,bp+fixed)
 got=runplan(st,hops,bursts,cost,C)
 if got!=exp:
  print('FAIL',trial,R,C,got,exp);raise SystemExit(1)
print('R7-10 FULL DP PASS',time.time()-t0)
